contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address logBefore, address logAfter) public payable {
        require(logBefore != address(0));
        require(logAfter != address(0));

        c.SetLogFile(logBefore); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        uint beforeBalance = address(c).balance;

        bool reverted;
        c.SetLogFile(logAfter); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBalance = address(c).balance;

        assert(reverted && afterBalance == beforeBalance);
    }

    receive() external payable {}
}

